def parse_qsl_(qs):
    """
    Parse a query string into a list of (key, value) tuples.
    - Separator: '&' only
    - '+' is decoded as space
    - Percent-escapes are decoded
    - Blank values are kept
    - Components without '=' yield (key, '')
    """
    # Unquote helper: decode percent-escapes and '+' as space
    def unquote(s):
        result = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '+':
                result.append(' ')
                i += 1
            elif c == '%' and i + 2 < n + 1 and i + 2 <= n - 1:
                # Check if next two chars are hex digits
                hex_chars = s[i+1:i+3]
                if len(hex_chars) == 2:
                    try:
                        byte_val = int(hex_chars, 16)
                        result.append(chr(byte_val))
                        i += 3
                    except ValueError:
                        result.append(c)
                        i += 1
                else:
                    result.append(c)
                    i += 1
            else:
                result.append(c)
                i += 1
        return ''.join(result)

    if not qs:
        return []

    pairs = []
    for part in qs.split('&'):
        if not part:
            continue
        if '=' in part:
            key, value = part.split('=', 1)
        else:
            key = part
            value = ''
        pairs.append((unquote(key), unquote(value)))

    return pairs
